// Twilio hits this URL when a call comes in, and expects TwiML (XML) back.
// Set ELEVENLABS_SIP_URI below to the SIP/stream URI from your ElevenLabs agent's
// phone number settings (only needed if you did NOT use ElevenLabs' built-in Twilio import).
const ELEVENLABS_SIP_URI = "sip:your-agent-id@sip.elevenlabs.io";

const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Dial>
    <Sip>${ELEVENLABS_SIP_URI}</Sip>
  </Dial>
</Response>`;

return [{ json: { twiml } }];
